{"label":"google-ads-philadelphia","action":"get_page_freeform_code","result":[{"location":"head","content":"<style>
@keyframes ga2-scroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.ga2-marquee-track{animation:ga2-scroll 32s linear infinite;will-change:transform}
@media(prefers-reduced-motion:reduce){.ga2-marquee-track{animation:none}}
</style>"},{"location":"footer","content":"<script>
(function(){
  var range=document.getElementById('ga2-range');
  if(range){
    var fill=document.getElementById('ga2-fill'),thumb=document.getElementById('ga2-thumb'),
        spendEl=document.getElementById('ga2-spend'),wasteEl=document.getElementById('ga2-waste'),
        saveEl=document.getElementById('ga2-save'),bw=document.getElementById('ga2-barwaste'),
        bk=document.getElementById('ga2-barwork');
    var MIN=500,MAX=20000,W=0.28,val=3000,drag=false;
    function fmt(n){return '$'+Math.round(n).toLocaleString('en-US');}
    function render(){var p=(val-MIN)/(MAX-MIN);fill.style.width=(p*100)+'%';thumb.style.left=(p*100)+'%';
      spendEl.textContent=fmt(val);var w=val*W;wasteEl.textContent=fmt(w);saveEl.textContent=fmt(w*12);
      bw.style.width=(W*100)+'%';bk.style.width=((1-W)*100)+'%';}
    function setX(x){var r=range.getBoundingClientRect();var p=Math.min(Math.max((x-r.left)/r.width,0),1);
      val=Math.round((MIN+p*(MAX-MIN))/100)*100;render();}
    range.addEventListener('pointerdown',function(e){drag=true;setX(e.clientX);try{range.setPointerCapture(e.pointerId);}catch(_){}});
    range.addEventListener('pointermove',function(e){if(drag)setX(e.clientX);});
    window.addEventListener('pointerup',function(){drag=false;});
    render();
  }
  var nums=document.querySelectorAll('.ga2-statnum .ga2-n');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){
      var el=e.target,t=parseInt(el.textContent,10),s=null;
      function step(ts){if(!s)s=ts;var p=Math.min((ts-s)/1100,1);el.textContent=Math.round(p*t);if(p<1)requestAnimationFrame(step);}
      requestAnimationFrame(step);io.unobserve(el);}});},{threshold:.6});
    nums.forEach(function(n){io.observe(n);});
  }
})();
</script>"}]}

