:root{--ease:cubic-bezier(.16,1,.3,1);--t-fast:.2s;--t-base:.32s;--t-slow:.6s}
.site-nav{transition:background var(--t-base) var(--ease),backdrop-filter var(--t-base) var(--ease),-webkit-backdrop-filter var(--t-base) var(--ease),border-color var(--t-base) var(--ease)}
