<script>
/* PMC v2 - MOTION (nav glass, hero parallax, stat count-up, marquee pause, timeline beam).
   Scroll reveals are owned by the unified .r-rev layer in Block 7, so the whole page
   shares one entrance curve and nothing double-animates. */
(function(){
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  /* Nav: dark glass after 20px */
  var nav = document.querySelector('.site-nav');
  if(nav){
    var navScroll = function(){ nav.classList.toggle('scrolled', (window.scrollY || window.pageYOffset) > 20); };
    navScroll();
    addEventListener('scroll', navScroll, {passive:true});
  }
  if(reduce) return;
  var hasIO = ('IntersectionObserver' in window);
  /* Hero canopy parallax, desktop only */
  var himg = document.querySelector('.hero-img');
  if(himg && innerWidth > 900){
    addEventListener('scroll', function(){
      var y = window.scrollY;
      if(y < innerHeight) himg.style.transform = 'scale(1.04) translateY(' + (y * 0.18) + 'px)';
    }, {passive:true});
  }
  /* Stat count-up (keeps the unit span beside the number) */
  var counts = document.querySelectorAll('.statbar .stat-n');
  if(counts.length && hasIO){
    var ioc = new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ upN(e.target); ioc.unobserve(e.target); } });
    }, {threshold:0.6});
    Array.prototype.forEach.call(counts, function(el){ ioc.observe(el); });
  }
  function upN(el){
    var tn = null, i;
    for(i=0;i<el.childNodes.length;i++){ var c = el.childNodes[i]; if(c.nodeType === 3 && /\d/.test(c.nodeValue)){ tn = c; break; } }
    if(!tn) return;
    var to = parseInt(tn.nodeValue.replace(/[^0-9]/g,''), 10);
    if(isNaN(to)) return;
    var t0 = performance.now();
    (function step(t){
      var p = Math.min((t - t0) / 1100, 1);
      tn.nodeValue = Math.round((1 - Math.pow(1 - p, 3)) * to);
      if(p < 1) requestAnimationFrame(step); else tn.nodeValue = to;
    })(performance.now());
  }
  /* Marquee: pause while the stats count up so the numbers land cleanly, then resume */
  var marqTrack = document.querySelector('.marquee-track');
  var statbar = document.querySelector('.statbar');
  if(marqTrack && statbar && hasIO){
    var iom = new IntersectionObserver(function(es){
      es.forEach(function(e){
        if(!e.isIntersecting) return;
        iom.unobserve(e.target);
        marqTrack.style.animationPlayState = 'paused';
        setTimeout(function(){ marqTrack.style.animationPlayState = ''; }, 2400);
      });
    }, {threshold:0.5});
    iom.observe(statbar);
  }
  /* 90-day timeline beam: draws left to right once the section is comfortably in view */
  var beam = document.querySelector('.plan-fill');
  var track = document.querySelector('#plan .phase') || document.querySelector('.plan-line') || document.querySelector('#plan');
  if(beam && track){
    beam.style.width = '0';
    beam.style.transition = 'width 1.8s cubic-bezier(.2,.7,.2,1)';
    if(hasIO){
      var iob = new IntersectionObserver(function(es){
        es.forEach(function(e){ if(e.isIntersecting){ beam.style.width = '100%'; iob.unobserve(e.target); } });
      }, {threshold:0.45});
      iob.observe(track);
    } else {
      beam.style.width = '100%';
    }
  }
})();
</script>
