<script>
(function(){
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches;
  if(reduce) return;
  function play(el){ el.classList.add('go'); }
  var icos = [].slice.call(document.querySelectorAll('.pmc-ico'));
  if(!icos.length) return;
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ play(e.target); io.unobserve(e.target); } });
    },{threshold:0.4});
    icos.forEach(function(el){ io.observe(el); });
  } else {
    icos.forEach(play);
  }
  icos.forEach(function(el){
    var host = el.closest('.svc, .leak-card, .sd-card, .path, [data-pmc-aw]') || el.parentElement;
    if(!host) return;
    host.addEventListener('mouseenter', function(){
      el.classList.remove('go'); void el.offsetWidth; el.classList.add('go');
    });
  });
  [].slice.call(document.querySelectorAll('.leak-card .pmc-ico')).forEach(function(el){ el.classList.add('go'); });
})();
</script>
<script>
/* PMC HOMEPAGE - AUDIT WIDGET LIVE WIRING (v1.1)
   sprint-2026-06-15-audit-widget-validation
   Changes from v1.0:
   - Pre-submit validation: reject placeholder / test domains before fetch
   - PLACEHOLDER_DOMAINS set + isPlaceholder() regex catches
   - Friendly error copy on bad input (no network call, no DB row)
*/
(function () {
  if (window.__pmc_audit) return;
  window.__pmc_audit = true;
  try { if (window.Webflow && Webflow.env && Webflow.env('design')) return; } catch (e) {}

  var SPRINT_SENTINEL = 'sprint-2026-06-15-audit-widget-validation';
  var API_URL = 'https://audit.pfendermarketing.com/api/scan';

  var PLACEHOLDER_DOMAINS = new Set([
    'example.com', 'example.org', 'example.net', 'example.edu',
    'test.com', 'test.org', 'test.net',
    'domain.com', 'mydomain.com', 'yourdomain.com',
    'website.com', 'mywebsite.com', 'yourwebsite.com',
    'sample.com', 'foo.com', 'bar.com', 'baz.com',
    'asdf.com', 'abc.com', '123.com', 'xyz.com',
    'localhost', '127.0.0.1', '0.0.0.0',
    'acme.com', 'acmecorp.com',
    'mycompany.com', 'yourcompany.com', 'companyname.com',
    'mybusiness.com', 'yourbusiness.com'
  ]);

  function isPlaceholder(host) {
    var h = host.replace(/^www\./i, '').toLowerCase();
    if (PLACEHOLDER_DOMAINS.has(h)) return true;
    var label = h.split('.')[0];
    if (/^[a-z]$/.test(label)) return true; // single-char: a.com, x.com
    if (/^\d+$/.test(label)) return true;   // all-digit: 456.com, 999.com
    return false;
  }

  var ICONS = {
    warn: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg>',
    error: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m15 9-6 6"></path><path d="m9 9 6 6"></path></svg>',
    ok: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg>'
  };
  var COLORS = {
    warn: { bg: 'rgba(215,175,51,0.10)', text: '#D7AF33' },
    error: { bg: 'rgba(217,82,82,0.10)', text: '#d95252' },
    ok: { bg: 'rgba(69,115,64,0.15)', text: '#5A9E54' }
  };
  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function buildRow(finding, isLast) {
    var sev = finding.severity in COLORS ? finding.severity : 'warn';
    var c = COLORS[sev];
    var ic = ICONS[sev];
    var border = isLast ? '' : 'border-bottom:1px solid rgba(245,240,232,0.04);';
    return '<div style="display:flex;align-items:center;gap:14px;padding:14px 0;' + border + '">' +
      '<div style="width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:' + c.bg + ';color:' + c.text + '">' + ic + '</div>' +
      '<div style="flex:1;min-width:0">' +
        '<div data-pmc-aw-row-title style="font-size:14px;color:#F5F0E8;font-weight:500;line-height:1.35;margin-bottom:2px">' + escapeHtml(finding.title) + '</div>' +
        '<div data-pmc-aw-row-meta style="font-size:12px;color:rgba(245,240,232,0.5)">' + escapeHtml(finding.meta) + '</div>' +
      '</div>' +
      '<div data-pmc-aw-row-metric data-pmc-aw-row-severity="' + sev + '" style="font-weight:700;font-size:18px;color:' + c.text + ';flex-shrink:0">' + escapeHtml(finding.metric) + '</div>' +
    '</div>';
  }
  var SCAN_STEPS = ['Fetching the page', 'Reading meta + schema', 'Checking page speed', 'Mapping the funnel', 'Tallying the leaks'];
  function initWidget(widget) {
    var input = widget.querySelector('[data-pmc-aw-input]');
    var submit = widget.querySelector('[data-pmc-aw-submit]');
    var status = widget.querySelector('[data-pmc-aw-status]');
    var stream = widget.querySelector('[data-pmc-aw-stream]');
    var titleEl = widget.querySelector('[data-pmc-aw-title]');
    var submitLabel = submit ? (submit.textContent || 'Find the leak').trim() : 'Find the leak';
    var theaterTimer = null;
    function startTheater() {
      var i = 0;
      if (submit) submit.textContent = SCAN_STEPS[0];
      theaterTimer = setInterval(function () {
        i = Math.min(i + 1, SCAN_STEPS.length - 1);
        if (submit) submit.textContent = SCAN_STEPS[i];
      }, 720);
    }
    function stopTheater() { if (theaterTimer) { clearInterval(theaterTimer); theaterTimer = null; } }
    function setLoading(on) {
      if (on) {
        widget.style.opacity = '0.92';
        if (status) { status.textContent = 'Scanning'; status.style.color = '#D7AF33'; }
        if (input) input.disabled = true;
        if (submit) { submit.disabled = true; submit.style.opacity = '0.85'; }
        startTheater();
      } else {
        stopTheater();
        widget.style.opacity = '1';
        if (input) input.disabled = false;
        if (submit) { submit.disabled = false; submit.textContent = submitLabel; submit.style.opacity = '1'; }
      }
    }
    function showError(msg) {
      if (status) { status.textContent = 'Error'; status.style.color = '#d95252'; }
      if (stream) stream.innerHTML = '<div style="padding:32px 0;text-align:center;font-size:13px;color:rgba(245,240,232,0.7)">' + escapeHtml(msg) + '</div>';
    }
    function renderFindings(findings, scannedUrl) {
      if (stream && Array.isArray(findings)) {
        stream.innerHTML = findings.map(function (f, i) { return buildRow(f, i === findings.length - 1); }).join('');
      }
      if (titleEl) {
        try { titleEl.textContent = new URL(scannedUrl).hostname; } catch (e) { titleEl.textContent = scannedUrl; }
      }
      if (status) { status.textContent = 'Result'; status.style.color = '#5A9E54'; }
    }
    async function scan(rawUrl) {
      var url = rawUrl.trim();
      if (!url) return;
      if (!/^https?:\/\//i.test(url)) url = 'https://' + url;

      // Pre-submit validation: reject placeholder / test domains.
      // No fetch, no DB row, no conversion event on bad input.
      try {
        var parsed = new URL(url);
        if (isPlaceholder(parsed.hostname)) {
          showError("That looks like a placeholder. Drop in your real website and we'll run the scan.");
          return;
        }
      } catch (e) {
        showError("That doesn't look like a valid URL. Try something like https://yoursite.com");
        return;
      }

      setLoading(true);
      try {
        var res = await fetch(API_URL + '?url=' + encodeURIComponent(url) + '&source=' + (widget.getAttribute('data-pmc-aw-source') || 'unknown'));
        var data = await res.json();
        if (data && data.error) showError(data.error);
        else if (data && Array.isArray(data.findings)) renderFindings(data.findings, data.url || url);
        else showError('Unexpected response. Try again.');
      } catch (e) {
        showError('Could not reach the audit service. Try again.');
      } finally {
        setLoading(false);
      }
    }
    if (submit) submit.addEventListener('click', function (e) { e.preventDefault(); if (input) scan(input.value); });
    if (input) input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); scan(input.value); } });
  }
  function init() { [].forEach.call(document.querySelectorAll('[data-pmc-aw]'), initWidget); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
</script>
<script>
/* PMC HOMEPAGE - AUDIT WIDGET CAPTURE FORM HANDLER (v1.1) */
(function () {
  if (window.__pmc_aw_capture) return;
  window.__pmc_aw_capture = true;
  var CAPTURE_URL = 'https://audit.pfendermarketing.com/api/capture';
  var REVEAL_DELAY_MS = 4000;
  function uuid() {
    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
      return window.crypto.randomUUID();
    }
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
      var r = (Math.random() * 16) | 0;
      var v = c === 'x' ? r : ((r & 0x3) | 0x8);
      return v.toString(16);
    });
  }
  function setState(captureRoot, state) {
    var nodes = captureRoot.querySelectorAll('[data-pmc-aw-capture-state]');
    nodes.forEach(function (el) {
      el.style.display = el.getAttribute('data-pmc-aw-capture-state') === state ? '' : 'none';
    });
  }
  function parseFindings(streamEl) {
    if (!streamEl) return [];
    var titles = streamEl.querySelectorAll('[data-pmc-aw-row-title]');
    var findings = [];
    titles.forEach(function (titleEl) {
      var rowParent = titleEl.parentElement && titleEl.parentElement.parentElement;
      if (!rowParent) return;
      var meta = rowParent.querySelector('[data-pmc-aw-row-meta]');
      var metric = rowParent.querySelector('[data-pmc-aw-row-metric]');
      var severity = metric ? (metric.getAttribute('data-pmc-aw-row-severity') || 'warn') : 'warn';
      findings.push({
        title: (titleEl.textContent || '').trim(),
        meta: meta ? (meta.textContent || '').trim() : '',
        severity: severity,
        metric: metric ? (metric.textContent || '').trim() : '',
      });
    });
    return findings;
  }
  function revealForm(capture) {
    if (capture.dataset.pmcRevealed === '1') return;
    capture.style.display = '';
    capture.style.opacity = '0';
    capture.style.transform = 'translateY(8px)';
    capture.dataset.pmcRevealed = '1';
    requestAnimationFrame(function () {
      capture.style.transition = 'opacity 400ms cubic-bezier(0.16,1,0.3,1), transform 400ms cubic-bezier(0.16,1,0.3,1)';
      capture.style.opacity = '1';
      capture.style.transform = 'translateY(0)';
    });
  }
  function initCapture(widget) {
    var capture = widget.querySelector('[data-pmc-aw-capture]');
    if (!capture) return;
    var lastScan = { url: null, scanned_at: null };
    var statusEl = widget.querySelector('[data-pmc-aw-status]');
    var titleEl = widget.querySelector('[data-pmc-aw-title]');
    var streamEl = widget.querySelector('[data-pmc-aw-stream]');
    var inputEl = widget.querySelector('[data-pmc-aw-input]');
    var form = capture.querySelector('[data-pmc-aw-capture-form]');
    var emailInput = capture.querySelector('[data-pmc-aw-capture-email]');
    var honeypotInput = capture.querySelector('[data-pmc-aw-capture-honeypot]');
    var retryBtn = capture.querySelector('[data-pmc-aw-capture-retry]');
    if (!statusEl || !form || !emailInput || !honeypotInput) return;
    var revealTimer = null;
    function checkScanComplete() {
      var text = (statusEl.textContent || '').trim().toLowerCase();
      if (text === 'result') {
        var resolvedUrl = null;
        if (inputEl && inputEl.value) {
          var raw = inputEl.value.trim();
          resolvedUrl = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
        } else if (titleEl) {
          var host = (titleEl.textContent || '').trim();
          resolvedUrl = host ? 'https://' + host : null;
        }
        lastScan.url = resolvedUrl;
        lastScan.scanned_at = new Date().toISOString();
        if (revealTimer) clearTimeout(revealTimer);
        revealTimer = setTimeout(function () { revealForm(capture); }, REVEAL_DELAY_MS);
      }
    }
    try {
      var observer = new MutationObserver(checkScanComplete);
      observer.observe(statusEl, { childList: true, characterData: true, subtree: true });
    } catch (e) {}
    checkScanComplete();
    function submit(e) {
      if (e) e.preventDefault();
      var email = (emailInput.value || '').trim();
      var honeypot = honeypotInput.value || '';
      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        emailInput.style.borderBottomColor = '#d95252';
        emailInput.focus();
        setTimeout(function () { emailInput.style.borderBottomColor = ''; }, 2400);
        return;
      }
      setState(capture, 'submitting');
      var findings = parseFindings(streamEl);
      var payload = {
        email: email,
        url: lastScan.url || (inputEl && inputEl.value) || window.location.href,
        scanned_at: lastScan.scanned_at || new Date().toISOString(),
        version: '1.0.0',
        source: 'homepage_widget',
        findings: findings,
        signals: {},
        honeypot: honeypot,
        request_id: uuid()
      };
      fetch(CAPTURE_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
        .then(function (res) {
          return res.json().catch(function () { return {}; }).then(function (data) {
            return { ok: res.status >= 200 && res.status < 300, status: res.status, data: data };
          });
        })
        .then(function (result) {
          if (result.ok) {
            setState(capture, 'success');
          } else {
            var errMsgEl = capture.querySelector('[data-pmc-aw-capture-error-msg]');
            if (errMsgEl) {
              var raw = result.data && result.data.error;
              var msg = 'Something went wrong. Please try again.';
              if (typeof raw === 'string') {
                msg = raw;
              } else if (raw && typeof raw === 'object') {
                if (typeof raw.message === 'string') msg = raw.message;
                else if (typeof raw.error === 'string') msg = raw.error;
              }
              errMsgEl.textContent = msg;
            }
            setState(capture, 'error');
          }
        })
        .catch(function () {
          var errMsgEl = capture.querySelector('[data-pmc-aw-capture-error-msg]');
          if (errMsgEl) errMsgEl.textContent = 'Could not reach the service. Try again.';
          setState(capture, 'error');
        });
    }
    form.addEventListener('submit', submit);
    if (retryBtn) {
      retryBtn.addEventListener('click', function (e) {
        e.preventDefault();
        setState(capture, 'idle');
      });
    }
  }
  function init() { [].forEach.call(document.querySelectorAll('[data-pmc-aw]'), initCapture); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
</script>
<style>
/* PMC HOMEPAGE - BOOK A CALL POPUP */
#pmc-book-overlay{position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;
  background:rgba(4,13,13,0.74);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);
