<script>
/* PMC HOMEPAGE - BOOK A CALL POPUP (lazy iframe, Tree CRM scheduling) */
(function () {
  if (window.__pmc_book) return;
  window.__pmc_book = true;
  var BOOK_URL = 'https://app.treecrm.co/book/discovery-call';
  var TREE_ORIGIN = 'https://app.treecrm.co';
  var TRIGGER_SEL = '[data-pmc-book], a[href="#book"], a[href$="/book/discovery-call"]';
  var overlay = null, frame = null, closeBtn = null, loadEl = null, loaded = false, lastFocus = null;
  function build() {
    overlay = document.createElement('div');
    overlay.id = 'pmc-book-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Book a discovery call');
    overlay.setAttribute('aria-hidden', 'true');
    overlay.innerHTML =
      '<div class="pb-dialog">' +
        '<div class="pb-head">' +
          '<div><p class="pb-title">Book a discovery call</p><span class="pb-sub">Pfender Marketing Co.</span></div>' +
          '<button class="pb-close" type="button" data-pmc-book-close aria-label="Close">' +
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M18 6 6 18M6 6l12 12"/></svg>' +
          '</button>' +
        '</div>' +
        '<div class="pb-body"><div class="pb-frame-wrap" data-pmc-book-frame>' +
          '<div class="pb-load" data-pmc-book-load><i></i>Loading the calendar</div>' +
        '</div></div>' +
      '</div>';
    document.body.appendChild(overlay);
    closeBtn = overlay.querySelector('[data-pmc-book-close]');
    loadEl = overlay.querySelector('[data-pmc-book-load]');
    closeBtn.addEventListener('click', close);
    overlay.addEventListener('click', function (e) { if (e.target === overlay) close(); });
  }
  function mountFrame() {
    if (loaded) return;
    loaded = true;
    var wrap = overlay.querySelector('[data-pmc-book-frame]');
    frame = document.createElement('iframe');
    frame.title = 'Book a discovery call';
    frame.setAttribute('allow', 'clipboard-write');
    frame.addEventListener('load', function () { if (loadEl) loadEl.style.display = 'none'; });
    frame.src = BOOK_URL;
    wrap.appendChild(frame);
  }
  function open() {
    if (!overlay) build();
    mountFrame();
    lastFocus = document.activeElement;
    overlay.classList.add('open');
    overlay.setAttribute('aria-hidden', 'false');
    document.documentElement.style.overflow = 'hidden';
    setTimeout(function () { if (closeBtn) closeBtn.focus(); }, 80);
  }
  function close() {
    if (!overlay) return;
    overlay.classList.remove('open');
    overlay.setAttribute('aria-hidden', 'true');
    document.documentElement.style.overflow = '';
    if (lastFocus && typeof lastFocus.focus === 'function') lastFocus.focus();
  }
  function readHeight(d) {
    if (d == null) return 0;
    if (typeof d === 'number') return d;
    if (typeof d === 'string') { var m = d.match(/(\d{2,5})/); return m ? parseInt(m[1], 10) : 0; }
    var h = d.height != null ? d.height : (d.payload && d.payload.height) || (d.data && d.data.height);
    return parseInt(h, 10) || 0;
  }
  function isResize(d) {
    if (typeof d === 'string') return d.indexOf('treecrm:embed:resize') === 0;
    if (d && typeof d === 'object') {
      var k = d.type || d.event || d.name;
      return k === 'treecrm:embed:resize';
    }
    return false;
  }
  window.addEventListener('message', function (e) {
    if (e.origin !== TREE_ORIGIN) return;
    if (!frame || !isResize(e.data)) return;
    var h = readHeight(e.data);
    if (h > 0) { frame.style.height = h + 'px'; if (loadEl) loadEl.style.display = 'none'; }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && overlay && overlay.classList.contains('open')) close();
  });
  document.addEventListener('click', function (e) {
    if (!e.target || !e.target.closest) return;
    var t = e.target.closest(TRIGGER_SEL);
    if (!t) return;
    e.preventDefault();
    open();
  });
})();
</script>
<!-- ============================================================
     BLOCK 7 - UNIFIED SECTION REVEAL
     Pairs with the .r-rev CSS that lives Inside <head>. One entrance
     for the whole page: fade up 26px over .8s on a single curve,
     staggered across siblings. This is now the ONLY scroll-reveal on
     the page (the old per-element reveal was removed from Block 2),
     so nothing double-animates. Loops, the tile color line, count-up
     and hovers are untouched.
     ============================================================ -->
<script>
(function(){
  function init(){
    if(window.__pmcReveal) return; window.__pmcReveal = true;
    var RM = window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches;
    if(RM) return;
    if(!('IntersectionObserver' in window)) return;
    var SEL = [
      '.sec-head','.sys-head','.os-head','.contact-head',
      '.stat',
      '.tc-head','.tc-frow','.tc-kpis','.tc-rail',
      '.mf-item','.mf-metrics',
      '.f-h2','.f-photo','.quote'
    ];
    var els = [];
    SEL.forEach(function(s){
      Array.prototype.forEach.call(document.querySelectorAll(s), function(el){
        if(els.indexOf(el) < 0) els.push(el);
      });
    });
    els.forEach(function(el){ el.classList.add('r-rev'); });
    var groups = [];
    els.forEach(function(el){
      var g = null;
      for(var i=0;i<groups.length;i++){ if(groups[i].p === el.parentNode){ g = groups[i]; break; } }
      if(!g){ g = {p: el.parentNode, items: []}; groups.push(g); }
      g.items.push(el);
    });
    groups.forEach(function(g){
      g.items.forEach(function(el,i){ el.style.transitionDelay = (Math.min(i,6) * 80) + 'ms'; });
    });
    var io = new IntersectionObserver(function(els){
      els.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('is-in'); io.unobserve(e.target); }
      });
    }, {threshold:0.1, rootMargin:'0px 0px -6% 0px'});
    els.forEach(function(el){ io.observe(el); });
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
